```java
public static String abbreviate(final String str, int offset, final int maxWidth) {
    if maxWidth < 4 → IllegalArgumentException("Minimum abbreviation width is 4")
    if str.length() <= maxWidth → str
    if offset > str.length() → offset = str.length()
    if str.length() - offset < maxWidth - 3 → offset = str.length() - (maxWidth - 3)
    if offset <= 4 → str.substring(0, maxWidth - 3) + "..."
    if maxWidth < 7 → IllegalArgumentException("Minimum abbreviation width with offset is 7")
    if offset + maxWidth - 3 < str.length() → "..." + abbreviate(str.substring(offset), maxWidth - 3)
    return "..." + str.substring(str.length() - (maxWidth - 3))
}
```

